document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();travel(-1)}if(e.key==='ArrowRight'){e.preventDefault();travel(1)}});
syncPrefs();refresh();

const bankMessages={activate:'Active Money Bubble dans Enable Banking : Activate by linking accounts, puis autorise ton compte BNP.',configuration:'Ajoute ENABLE_BANKING_PRIVATE_KEY dans Vercel, puis redéploie.',provider_configuration:'Vérifie la clé et active l’application dans Enable Banking (« Activate by linking accounts »).',no_accounts:'BNP a validé l’accès mais Enable Banking ne renvoie aucun compte. Vérifie les comptes autorisés dans Enable Banking.',unsupported_accounts:'Aucun compte en euros utilisable n’a été renvoyé par BNP.',link_accounts:'Dans Enable Banking, active Money Bubble avec « Activate by linking accounts », puis reconnecte ici.',bnp_unavailable:'Le connecteur BNP Paribas France n’est pas disponible.',rate_limit:'BNP limite les actualisations. Réessaie plus tard.',reconnect:'L’autorisation a expiré. Reconnecte BNP.',state:'Connexion expirée. Recommence depuis l’app.',cancelled:'Connexion annulée.',history_limit:'Historique trop volumineux. Aucune donnée partielle affichée.',account:'Compte non autorisé.',unavailable:'Connexion indisponible. Réessaie.',bank_unavailable:'La banque ou Enable Banking ne répond pas. Réessaie plus tard.'};
async function bankRequest(path,body){const response=await fetch('/api/bank/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store'});const result=await response.json();if(!response.ok)throw Object.assign(Error(bankMessages[result.error]||bankMessages.unavailable),{code:result.error});return result}
function bankControls(connected){$('connectBank').hidden=connected;$('syncBank').hidden=!connected;$('disconnectBank').hidden=!connected;$('bankAccountLabel').hidden=!connected||bankAccounts.length<2;for(const id of ['connectBank','syncBank','disconnectBank','bankAccount'])$(id).disabled=bankBusy}
async function syncBank(force=false){if(bankBusy||document.hidden||(!force&&Date.now()-bankLastSync<600000))return;bankBusy=true;bankControls(true);$('bankStatus').textContent='Actualisation…';try{const result=await bankRequest('sync',{accountId:bankAccountId});const transactions=validateImport(result);data=transactions;demo=false;bankActive=true;bankBalance=result.balance;bankAccountId=result.accountId;bankUpdatedAt=result.updatedAt;bankLastSync=Date.now();refresh();$('bankStatus').textContent='BNP · '+new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit'}).format(new Date(result.updatedAt));}catch(e){$('bankStatus').textContent=e.message;if(e.code==='reconnect'){bankActive=false;bankAccounts=[];bankBalance=null;const stored=read(keys.tx,null);try{data=stored?validateImport(stored):buildDemo();demo=!stored}catch{data=buildDemo();demo=true}refresh();bankControls(false)}}finally{bankBusy=false;bankControls(bankActive||!!bankAccounts.length)}}
$('connectBank').onclick=async()=>{if(bankBusy)return;bankBusy=true;bankControls(false);$('bankStatus').textContent='Ouverture de BNP…';try{const result=await bankRequest('start',{});location.assign(result.url)}catch(e){$('bankStatus').textContent=e.message;bankBusy=false;bankControls(false)}};
$('syncBank').onclick=()=>syncBank(true);
$('bankAccount').onchange=()=>{bankAccountId=$('bankAccount').value;data=[];bankBalance=null;refresh();syncBank(true)};
$('disconnectBank').onclick=async()=>{if(bankBusy)return;bankBusy=true;bankControls(true);try{await bankRequest('disconnect',{});bankActive=false;bankAccounts=[];bankBalance=null;bankAccountId=null;bankLastSync=0;const stored=read(keys.tx,null);try{data=stored?validateImport(stored):buildDemo();demo=!stored}catch{data=buildDemo();demo=true}refresh();$('bankStatus').textContent='Banque déconnectée.'}catch(e){$('bankStatus').textContent=e.message}finally{bankBusy=false;bankControls(bankActive)}};
async function initBank(){try{const status=await bankRequest('status');if(!status.configured){$('bankStatus').textContent=bankMessages.configuration;$('connectBank').disabled=true;return}bankAccounts=status.accounts||[];bankControls(status.connected);$('bankStatus').textContent=status.connected?'BNP connecté.':'BNP non connecté.';const select=$('bankAccount');select.replaceChildren();for(const a of bankAccounts){const o=document.createElement('option');o.value=a.id;o.textContent=a.name;select.append(o)}bankAccountId=bankAccounts.find(a=>a.type==='CACC')?.id||bankAccounts[0]?.id||null;if(bankAccountId)select.value=bankAccountId;if(status.connected){bankActive=true;data=[];demo=false;refresh();await syncBank(true)}}catch{$('bankStatus').textContent=bankMessages.unavailable;$('connectBank').disabled=true}}
const bankQuery=new URL(location.href).searchParams.get('bank');if(bankQuery){history.replaceState(null,'',location.pathname);if(bankQuery!=='connected'){$('settings').showModal();$('bankStatus').textContent=bankMessages[bankQuery]||bankMessages.unavailable;toast(bankMessages[bankQuery]||bankMessages.unavailable)}}
initBank().then(()=>{if(bankQuery&&bankQuery!=='connected')$('bankStatus').textContent=bankMessages[bankQuery]||bankMessages.unavailable});
window.addEventListener('focus',()=>{if(bankActive)syncBank()});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&bankActive)syncBank()});setInterval(()=>{if(bankActive)syncBank()},600000);
